gcuq(){return"\u0628\u062f\u0648\u0646 \u06a9\u0644\u06cc\u062f"},
gcui(){return"\u0628\u0627\u0632\u062f\u06cc\u062f\u06a9\u0646\u0646\u062f\u0647 \u062f\u0631 \u062d\u0627\u0644 \u062a\u0627\u06cc\u067e \u0627\u0633\u062a\u2026"},
gcuu(){return"\u0627\u0631\u0633\u0627\u0644 \u0634\u062f"},
gcut(){return"\u062e\u0648\u0627\u0646\u062f\u0647 \u0634\u062f"},
gctv(){return"\u067e\u06cc\u0627\u0645 \u0635\u0648\u062a\u06cc \u062f\u0631 \u0686\u062a \u0648\u0628"},
gctu(){return"\u067e\u06cc\u0627\u0645\u200c\u0647\u0627\u06cc \u0635\u0648\u062a\u06cc \u06a9\u0648\u062a\u0627\u0647 (\u0628\u0627\u0632\u062f\u06cc\u062f\u06a9\u0646\u0646\u062f\u0647 \u06cc\u0627 \u0627\u067e\u0631\u0627\u062a\u0648\u0631) \u0645\u0627\u0646\u0646\u062f \u0647\u0631 \u0641\u0627\u06cc\u0644 \u062f\u0631 \u0641\u0636\u0627\u06cc \u0630\u062e\u06cc\u0631\u0647\u200c\u0633\u0627\u0632\u06cc \u06a9\u0633\u0628\u200c\u0648\u06a9\u0627\u0631 \u062d\u0633\u0627\u0628 \u0645\u06cc\u200c\u0634\u0648\u0646\u062f."},
gcuI(){return"\u067e\u06cc\u0627\u0645 \u0635\u0648\u062a\u06cc \u062a\u0648\u0633\u0637 \u0628\u0627\u0632\u062f\u06cc\u062f\u06a9\u0646\u0646\u062f\u0647\u0654 \u0633\u0627\u06cc\u062a"},
gbmd(){return"\u0637\u0628\u0642 \u062a\u0646\u0638\u06cc\u0645\u0627\u062a \u06a9\u0633\u0628\u200c\u0648\u06a9\u0627\u0631 \u0648 \u067e\u0644\u0646 \u0641\u0636\u0627. \u0645\u06cc\u200c\u062a\u0648\u0627\u0646\u06cc\u062f \u0641\u0642\u0637 \u0631\u0648\u06cc \u0647\u0645\u06cc\u0646 \u0648\u06cc\u062c\u062a \u063a\u06cc\u0631\u0641\u0639\u0627\u0644 \u06a9\u0646\u06cc\u062f."},
gbmc(){return"\u067e\u06cc\u0627\u0645 \u0635\u0648\u062a\u06cc \u062f\u0631 \u062a\u0646\u0638\u06cc\u0645\u0627\u062a CRM \u06a9\u0633\u0628\u200c\u0648\u06a9\u0627\u0631 \u062e\u0627\u0645\u0648\u0634 \u0627\u0633\u062a \u06cc\u0627 \u062f\u0631 \u0627\u06cc\u0646 \u0648\u06cc\u062c\u062a \u0645\u062d\u062f\u0648\u062f \u0634\u062f\u0647 \u0627\u0633\u062a."},
gcuJ(){return"\u067e\u06cc\u0627\u0645 \u0635\u0648\u062a\u06cc \u0628\u0631\u0627\u06cc \u0627\u06cc\u0646 \u06a9\u0633\u0628\u200c\u0648\u06a9\u0627\u0631 \u062f\u0631 \u062a\u0646\u0638\u06cc\u0645\u0627\u062a CRM \u063a\u06cc\u0631\u0641\u0639\u0627\u0644 \u0627\u0633\u062a"},
