gcin(){return"\u067e\u0646\u0644 \u06a9\u0633\u0628\u200c\u0648\u06a9\u0627\u0631 (\u062f\u0633\u06a9\u062a\u0627\u067e)"},
gcip(){return"\u0635\u0641\u062d\u0647\u0654 \u0648\u0627\u062d\u062f"},
gciq(){return"\u062f\u0631 \u0647\u0631 \u0632\u0645\u0627\u0646 \u0641\u0642\u0637 \u06cc\u06a9 \u0635\u0641\u062d\u0647 \u0628\u0627\u0632 \u0627\u0633\u062a (\u0646\u0627\u0648\u0628\u0631\u06cc \u06a9\u0644\u0627\u0633\u06cc\u06a9)"},
gcir(){return"\u062a\u0628 \u062f\u0631 \u0646\u0648\u0627\u0631 \u0628\u0627\u0644\u0627"},
gcis(){return"\u0686\u0646\u062f \u0635\u0641\u062d\u0647 \u0628\u0627\u0632 \u0628\u0645\u0627\u0646\u062f \u0648 \u0628\u0627 \u062a\u0628\u200c\u0647\u0627\u06cc \u0646\u0648\u0627\u0631 \u062a\u06cc\u0631\u0647 \u0628\u0627\u0644\u0627\u06cc \u067e\u0646\u0644 \u062c\u0627\u0628\u0647\u200c\u062c\u0627 \u0634\u0648\u06cc\u062f (\u0641\u0642\u0637 \u062f\u0633\u06a9\u062a\u0627\u067e). \u062a\u0628\u200c\u0647\u0627\u06cc \u067e\u0633\u200c\u0632\u0645\u06cc\u0646\u0647 \u062f\u0631 \u062d\u0627\u0641\u0638\u0647 \u0645\u06cc\u200c\u0645\u0627\u0646\u0646\u062f\u061b \u06a9\u0644\u06cc\u062f \u067e\u0627\u06cc\u062f\u0627\u0631 \u0645\u0633\u06cc\u0631 \u0628\u0631\u0627\u06cc \u0628\u0627\u0632\u06af\u0634\u062a \u0628\u0647\u062a\u0631 \u0628\u0647 \u0647\u0645\u0627\u0646 \u062a\u0628 \u0647\u0645\u200c\u0633\u0648 \u0628\u0627 \u0631\u0648\u062a\u0631 \u0627\u0633\u062a."},
gcio(){return"\u062d\u0627\u0644\u062a \u062a\u0628 \u0641\u0642\u0637 \u062f\u0631 \u0639\u0631\u0636 \u0632\u06cc\u0627\u062f \u0627\u0639\u0645\u0627\u0644 \u0645\u06cc\u200c\u0634\u0648\u062f\u061b \u062f\u0631 \u0645\u0648\u0628\u0627\u06cc\u0644 \u0647\u0645\u06cc\u0634\u0647 \u062d\u0627\u0644\u062a \u062a\u06a9\u200c\u0635\u0641\u062d\u0647 \u0627\u0633\u062a."},
