gcNK(){return"\u0648\u0631\u0648\u062f \u0628\u0647 \u0627\u067e \u0627\u0632 \u067e\u0631\u0648\u0641\u0627\u06cc\u0644"},
gcNJ(){return"\u0627\u0632 \u0627\u06cc\u0646 \u0628\u0647 \u0628\u0639\u062f \u0628\u0627 \u0628\u0627\u0632 \u06a9\u0631\u062f\u0646 \u0627\u067e \u0628\u0647 \u067e\u0631\u0648\u0641\u0627\u06cc\u0644 \u0645\u06cc\u200c\u0631\u0648\u06cc\u062f\u061b \u0628\u0631\u0627\u06cc \u0644\u0627\u0646\u0686\u0631 \u062f\u0648\u0628\u0627\u0631\u0647 \u0627\u0632 \u0644\u06cc\u0633\u062a \u06a9\u0633\u0628\u200c\u0648\u06a9\u0627\u0631 \u0627\u0646\u062a\u062e\u0627\u0628 \u06a9\u0646\u06cc\u062f."},
gcND(){return"\u0628\u0647 \u0627\u06cc\u0646 \u06a9\u0633\u0628\u200c\u0648\u06a9\u0627\u0631 \u062f\u0633\u062a\u0631\u0633\u06cc \u0646\u062f\u0627\u0631\u06cc\u062f \u06cc\u0627 \u062d\u0630\u0641 \u0634\u062f\u0647 \u0627\u0633\u062a."},
