gcNT(){return"\u0645\u062c\u0645\u0648\u0639 \u0641\u0631\u0648\u0634"},
gcNS(){return"\u062a\u0631\u0627\u06a9\u0646\u0634\u200c\u0647\u0627\u06cc \u0627\u062e\u06cc\u0631"},
gcNO(){return"\u0628\u0631\u0627\u06cc \u0646\u0642\u0634 \u0634\u0645\u0627 \u0645\u06cc\u0627\u0646\u0628\u0631\u06cc \u062f\u0631 \u062f\u0633\u062a\u0631\u0633 \u0646\u06cc\u0633\u062a. \u067e\u0646\u0644 \u06a9\u0627\u0645\u0644 \u0631\u0627 \u0628\u0627\u0632 \u06a9\u0646\u06cc\u062f \u06cc\u0627 \u0627\u0632 \u0645\u062f\u06cc\u0631 \u062f\u0633\u062a\u0631\u0633\u06cc \u0628\u062e\u0648\u0627\u0647\u06cc\u062f."},
gcNL(){return"\u067e\u06cc\u0634\u200c\u0646\u0645\u0627\u06cc\u0634 \u0632\u0646\u062f\u0647"},
gcNW(){return"\u062a\u0631\u0627\u06a9\u0645 \u06a9\u0627\u0634\u06cc\u200c\u0647\u0627"},
gcNV(){return"\u062a\u0639\u062f\u0627\u062f \u0645\u06cc\u0627\u0646\u0628\u0631 \u062f\u0631 \u0647\u0631 \u0631\u062f\u06cc\u0641 \u0631\u0627 \u0627\u0646\u062a\u062e\u0627\u0628 \u06a9\u0646\u06cc\u062f."},
gcNH(){return"\u0631\u0627\u062d\u062a"},
gcNI(){return"\u0641\u0634\u0631\u062f\u0647"},
gcNE(){return"\u0628\u0627\u0631\u06af\u0630\u0627\u0631\u06cc \u06a9\u0633\u0628\u200c\u0648\u06a9\u0627\u0631\u0647\u0627 \u0646\u0627\u0645\u0648\u0641\u0642 \u0628\u0648\u062f."},
gcNN(){return"\u06a9\u0633\u0628\u200c\u0648\u06a9\u0627\u0631\u06cc \u06cc\u0627\u0641\u062a \u0646\u0634\u062f."},
gcos(){return"\u0627\u0628\u0632\u0627\u0631\u0647\u0627\u06cc \u0628\u06cc\u0634\u062a\u0631"},
gbjN(){return"\u0686\u062a \u0633\u0631\u06cc\u0639 \u0628\u0627 AI (\u0646\u06af\u0647\u200c\u062f\u0627\u0634\u062a\u0646: \u0644\u0627\u0646\u0686\u0631 \xb7 Hold Q \u0633\u067e\u0633 AI)"},
gbhQ(){return"\u062f\u0633\u062a\u06cc\u0627\u0631 \u0647\u0648\u0634\u0645\u0646\u062f"},
gcec(){return"\u062f\u0631 \u0686\u0647 \u0645\u0648\u0631\u062f\u06cc \u06a9\u0645\u06a9 \u0645\u06cc\u200c\u062e\u0648\u0627\u0647\u06cc\u062f\u061f"},
gce8(){return"\u0645\u0648\u0636\u0648\u0639 \u0631\u0627 \u0628\u0646\u0648\u06cc\u0633\u06cc\u062f \u0648 Enter \u0628\u0632\u0646\u06cc\u062f\u2026"},
gce9(){return"Enter \u0628\u0631\u0627\u06cc \u0627\u0631\u0633\u0627\u0644 \xb7 Esc \u0628\u0631\u0627\u06cc \u0628\u0633\u062a\u0646 \xb7 Hold Q \u0633\u067e\u0633 AI"},
gce7(){return"AI \u0631\u0627 \u062a\u0627\u06cc\u067e \u06a9\u0646\u06cc\u062f\u2026"},
gcea(){return"\u0628\u0631\u0627\u06cc \u0627\u0633\u062a\u0641\u0627\u062f\u0647 \u0627\u0632 \u062f\u0633\u062a\u06cc\u0627\u0631 \u0647\u0648\u0634\u0645\u0646\u062f \u0627\u0628\u062a\u062f\u0627 \u06cc\u06a9 \u06a9\u0633\u0628\u200c\u0648\u06a9\u0627\u0631 \u0631\u0627 \u0628\u0627\u0632 \u06a9\u0646\u06cc\u062f."},
gceb(){return"\u0628\u0631\u0627\u06cc \u0627\u0633\u062a\u0641\u0627\u062f\u0647 \u0627\u0632 \u062f\u0633\u062a\u06cc\u0627\u0631 \u0647\u0648\u0634\u0645\u0646\u062f \u0648\u0627\u0631\u062f \u062d\u0633\u0627\u0628 \u0634\u0648\u06cc\u062f."},
gbjO(){return"\u0645\u0627\u0634\u06cc\u0646 \u062d\u0633\u0627\u0628"},
